#!/system/bin/sh
# Self-contained loader for gc_memory.ko (Android 13, generic GKI 5.10 arm64).
# The embedded module remains a real ELF .ko; this script only extracts and loads it.

set -u

EXPECTED_SHA256="8e75ad3911980d19534900d38146809f123bed4ab49b803f25647fc59dae76f7"
TMP="${TMPDIR:-/data/local/tmp}/.gc-memory-$$.ko"

cleanup() { rm -f "$TMP"; }
trap cleanup EXIT INT TERM

if [ "$(id -u 2>/dev/null)" != "0" ]; then
    echo "error: run as root: su -c '$0'" >&2
    exit 10
fi

case "$(uname -m 2>/dev/null)" in
    aarch64|arm64) ;;
    *) echo "error: this module is ARM64 only" >&2; exit 11 ;;
esac

case "$(uname -r 2>/dev/null)" in
    5.10*) ;;
    *) echo "error: this generic build is only for kernel 5.10" >&2; exit 12 ;;
esac

if command -v base64 >/dev/null 2>&1; then
    base64 -d > "$TMP" <<'GC_MEMORY_KO_BASE64'
