chmod 600 "$TMP" || exit 14
if command -v sha256sum >/dev/null 2>&1; then
    ACTUAL="$(sha256sum "$TMP" | awk '{print $1}')"
    if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
        echo "error: embedded module checksum mismatch" >&2
        exit 15
    fi
fi

if ! insmod "$TMP"; then
    echo "error: insmod failed" >&2
    echo "kernel: $(uname -r)" >&2
    echo "This generic module has vermagic 5.10.223-ga0cedc522d8b." >&2
    echo "Check: dmesg | tail -50" >&2
    exit 20
fi

echo "gc_memory loaded successfully"
echo "Now run: /data/local/tmp/xvcen --kernel-check"
exit 0
